mapper.select:
select cc_id, instance_id, process_key, process_name, business_key, title,
       task_id, task_name, sender_id, sender_name, receiver_id, receiver_name,
       read_flag, read_time, create_time
from flow_cc

    and receiver_id = #{receiverId}
    and title like concat('%', #{title}, '%')
    and process_key = #{processKey}
    and read_flag = #{readFlag}
    and create_time >= #{params.beginTime}
    and create_time <= concat(#{params.endTime}, ' 23:59:59')

order by read_flag asc, create_time desc, cc_id desc

select count(1) from flow_cc
where instance_id = #{instanceId}
  and task_id = #{taskId}
  and receiver_id = #{receiverId}
